//! M9 tier-B (ADR-0002): riv-ir `Design` → standalone Rust source. The
//! generated file compiles against the runtime crates (vl-values / riv-ir
//! / riv-kernel display face) and reproduces the interpreter's stdout
//! byte-exact on the ADR-0002 subset; anything outside the subset is a
//! hard error with a milestone pointer (iron rule 3).
//!
//! Semantics parity is structural, not re-implemented: every value op in
//! the generated code calls the SAME vl-ops function the kernel's eval
//! calls, and $display formatting goes through the ONE kernel face
//! (riv_kernel::render_pieces).
//!
//! Slice-2 subset: N initial threads (declaration order), straight-line
//! segment bodies, suspension ONLY via Delay (#0 → the inactive region;
//! #n → the wheel), delayed NBAs (AssignNbaDelay), $finish. The embedded
//! scheduler mirrors ADR-0001: active FIFO drain → inactive region → NBA
//! batch → wheel advance (delayed NBAs due at the new time commit before
//! the woken threads run).

use riv_ir::{Design, FmtPiece, Lval, Op, SysId, ThreadKind};

pub const MILESTONE: &str = "milestone M9";

fn err(what: &str) -> String {
    format!("--gen-rust: {what} not supported yet ({MILESTONE})")
}

/// Generate a standalone Rust program for `d`.
pub fn gen(d: &Design) -> Result<String, String> {
    if !d.gates.is_empty() {
        return Err(err("gate primitives"));
    }
    for t in &d.threads {
        if t.kind != ThreadKind::Initial || !t.sens.is_empty() {
            return Err(err("non-initial threads"));
        }
        // Suspension whitelist for the segment scheduler: Delay only.
        for op in &t.body {
            if let Op::WaitEdge { .. }
            | Op::Fork { .. }
            | Op::JoinDone
            | Op::JoinPoint
            | Op::Branch { .. }
            | Op::Jump { .. }
            | Op::Call { .. }
            | Op::LoadElem { .. }
            | Op::LoadPartDyn { .. }
            | Op::LoadBit { .. }
            | Op::AssignForce { .. }
            | Op::Release { .. } = op
            {
                return Err(err(&format!("op {op:?}")));
            }
            if let Op::AssignNbaDelay { lv, .. } = op {
                if !matches!(lv, Lval::Var { .. }) {
                    return Err(err("bit/part-select delayed NBA targets"));
                }
            }
            if let Op::AssignBlk { lv, .. } | Op::AssignNba { lv, .. } = op {
                if !matches!(lv, Lval::Var { .. }) {
                    return Err(err("bit/part-select assignment targets"));
                }
            }
        }
    }

    let mut g = Gen::new(d);
    g.preamble();
    for (ti, t) in d.threads.iter().enumerate() {
        g.emit_thread(ti, t)?;
    }
    g.out.push_str(RUNTIME);
    Ok(g.out)
}

struct Gen<'a> {
    d: &'a Design,
    out: String,
}

impl<'a> Gen<'a> {
    fn new(d: &'a Design) -> Self {
        Gen { d, out: String::new() }
    }

    fn preamble(&mut self) {
        let d = self.d;
        let n = d.threads.len();
        self.out.push_str("// Generated by rcs riv-gen (M9 tier-B, ADR-0002) — do not edit.\n");
        self.out.push_str("#![allow(warnings)]\n");
        self.out.push_str("use vl_values::Bits;\n\n");
        self.out.push_str("fn main() -> Result<(), Box<dyn std::error::Error>> {\n");
        // Vars: init materialization (vl_ops::parse_const — the same
        // literal path the kernel uses) + 2-state projection at the
        // storage boundary (the --binary face runs projected).
        self.out.push_str("    let mut vars: Vec<Bits> = Vec::new();\n");
        for v in &d.vars {
            let init = match &v.init {
                Some(lit) => format!(
                    "vl_ops::parse_const(&riv_ir::Literal {{ width: {}, signed: {}, base: riv_ir::Base::{:?}, digits: {:?}.to_string() }})",
                    lit.width, lit.signed, lit.base, lit.digits
                ),
                None => format!("Bits::all_x({})", v.width),
            };
            self.out.push_str(&format!(
                "    vars.push(({init}).map_err(|e| e.0)?.to_2state().map_err(|e| e.0)?); // {}\n",
                v.name
            ));
        }
        // Per-thread slot frames.
        self.out.push_str("    let mut slot_frames: Vec<Vec<Bits>> = Vec::new();\n");
        for t in &d.threads {
            self.out.push_str(&format!(
                "    slot_frames.push(vec![Bits::zeros(1).map_err(|e| e.0)?; {}]);\n",
                t.frame_len
            ));
        }
        self.out.push_str(&format!(
            "    let mut rt = Rt::new({:?});\n",
            d.meta.timescale
        ));
        self.out.push_str(&format!(
            "    let threads: [ThreadFn; {n}] = [{}];\n",
            (0..n).map(|i| format!("t{i}")).collect::<Vec<_>>().join(", ")
        ));
        self.out.push_str("    rt.run_all(&mut vars, &mut slot_frames, &threads);\n");
        self.out.push_str("    rt.flush(&mut vars);\n    Ok(())\n}\n\n");
    }

    /// One thread = a state machine whose states are the straight-line
    /// segments between Delay suspensions (ADR-0002 §4: #0 → inactive
    /// region, #n → the wheel; NBAs queue to the owning time step).
    fn emit_thread(&mut self, ti: usize, t: &riv_ir::Thread) -> Result<(), String> {
        self.out.push_str(&format!(
            "fn t{ti}(rt: &mut Rt, vars: &mut Vec<Bits>, slots: &mut Vec<Bits>, st: &mut u32) -> Result<Susp, Box<dyn std::error::Error>> {{\n    loop {{\n        match *st {{\n"
        ));
        // Split the body into segments at Delay ops.
        let mut segments: Vec<Vec<&Op>> = vec![Vec::new()];
        for op in &t.body {
            segments.last_mut().unwrap().push(op);
            if let Op::Delay { .. } = op {
                // The Delay TERMINATES its segment: `let d` is emitted as
                // the segment's last statement, then the state return
                // routes it (measured: splitting after the delay op left
                // the delay in the NEXT segment and the previous state
                // returned Done — the thread died at its first #).
                segments.push(Vec::new());
            }
        }
        // A trailing empty segment (EndThread after a Delay) collapses.
        if segments.last().is_some_and(|s| s.is_empty()) {
            segments.pop();
        }
        for (si, seg) in segments.iter().enumerate() {
            self.out.push_str(&format!("            {si} => {{\n"));
            let ends_with_delay = matches!(seg.last(), Some(Op::Delay { .. }));
            for op in seg {
                let finished = matches!(
                    op,
                    Op::SysCall { id: SysId::Finish, .. }
                );
                self.emit_op(op)?;
                if finished {
                    // $finish halts the thread immediately (kernel: the
                    // remaining segment never runs) — trailing ops would
                    // be unreachable code in the generated body.
                    break;
                }
            }
            if ends_with_delay {
                self.out.push_str(&format!(
                    "                *st = {}; return Ok(Susp::Delay(d));\n",
                    si + 1
                ));
            } else {
                self.out.push_str(&format!(
                    "                *st = {}; return Ok(Susp::Done);\n",
                    si + 1
                ));
            }
            self.out.push_str("            }\n");
        }
        self.out.push_str("            _ => return Ok(Susp::Done),\n");
        self.out.push_str("        }\n    }\n}\n\n");
        Ok(())
    }

    fn emit_op(&mut self, op: &Op) -> Result<(), String> {
        let d = self.d;
        let s = |sl: u32| format!("slots[{sl}]");
        let v = |sl: u32| format!("slots[{sl}].clone()");
        match op {
            Op::Const { dst, lit } => {
                self.out.push_str(&format!(
                    "    {} = vl_ops::parse_const(&riv_ir::Literal {{ width: {}, signed: {}, base: riv_ir::Base::{:?}, digits: {:?}.to_string() }}).map_err(|e| e.0)?;\n",
                    s(*dst), lit.width, lit.signed, lit.base, lit.digits
                ));
            }
            Op::Mov { dst, src } => {
                self.out.push_str(&format!("    {} = {};\n", s(*dst), v(*src)));
            }
            Op::Bin { kind, dst, a, b, w, signed } => {
                self.out.push_str(&format!(
                    "    {} = vl_ops::apply_bin(riv_ir::BinKind::{kind:?}, &{}, &{}, {w}, {signed}).map_err(|e| e.0)?;\n",
                    s(*dst), v(*a), v(*b)
                ));
            }
            Op::Bit { kind, dst, a, b, w, signed } => {
                self.out.push_str(&format!(
                    "    {} = vl_ops::apply_bit(riv_ir::BitKind::{kind:?}, &{}, &{}, {w}, {signed}).map_err(|e| e.0)?;\n",
                    s(*dst), v(*a), v(*b)
                ));
            }
            Op::BitXnor { dst, a, b, w } => {
                self.out.push_str(&format!(
                    "    {} = vl_ops::apply_bit_xnor(&{}, &{}, {w}).map_err(|e| e.0)?;\n",
                    s(*dst), v(*a), v(*b)
                ));
            }
            Op::BitNot { dst, a, w, signed } => {
                self.out.push_str(&format!(
                    "    {} = vl_ops::apply_bit_not(&{}, {w}, {signed}).map_err(|e| e.0)?;\n",
                    s(*dst), v(*a)
                ));
            }
            Op::Reduce { kind, dst, a } => {
                self.out.push_str(&format!(
                    "    {} = vl_ops::apply_reduce(riv_ir::RedKind::{kind:?}, &{}).map_err(|e| e.0)?;\n",
                    s(*dst), v(*a)
                ));
            }
            Op::LogicAnd { dst, a, b } => {
                self.out.push_str(&format!(
                    "    {} = vl_ops::apply_logic_and(&{}, &{}).map_err(|e| e.0)?;\n",
                    s(*dst), v(*a), v(*b)
                ));
            }
            Op::LogicOr { dst, a, b } => {
                self.out.push_str(&format!(
                    "    {} = vl_ops::apply_logic_or(&{}, &{}).map_err(|e| e.0)?;\n",
                    s(*dst), v(*a), v(*b)
                ));
            }
            Op::LogicNot { dst, a } => {
                self.out.push_str(&format!(
                    "    {} = vl_ops::apply_logic_not(&{}).map_err(|e| e.0)?;\n",
                    s(*dst), v(*a)
                ));
            }
            Op::Cmp { kind, dst, a, b, signed } => {
                self.out.push_str(&format!(
                    "    {} = vl_ops::apply_cmp(riv_ir::CmpKind::{kind:?}, &{}, &{}, {signed}).map_err(|e| e.0)?;\n",
                    s(*dst), v(*a), v(*b)
                ));
            }
            Op::CaseCmp { kind, dst, a, b } => {
                self.out.push_str(&format!(
                    "    {} = vl_ops::apply_case_cmp(riv_ir::CaseCmpKind::{kind:?}, &{}, &{}).map_err(|e| e.0)?;\n",
                    s(*dst), v(*a), v(*b)
                ));
            }
            Op::Shift { kind, dst, a, b, w, signed } => {
                self.out.push_str(&format!(
                    "    {} = vl_ops::apply_shift(riv_ir::ShiftKind::{kind:?}, &{}, &{}, {w}, {signed}).map_err(|e| e.0)?;\n",
                    s(*dst), v(*a), v(*b)
                ));
            }
            Op::Sel { dst, cond, a, b } => {
                self.out.push_str(&format!(
                    "    {} = vl_ops::apply_sel(&{}, &{}, &{}).map_err(|e| e.0)?;\n",
                    s(*dst), v(*cond), v(*a), v(*b)
                ));
            }
            Op::Concat { dst, parts } => {
                let list = parts.iter().map(|p| v(*p)).collect::<Vec<_>>().join(", ");
                self.out.push_str(&format!(
                    "    {} = vl_ops::apply_concat(&[{list}]).map_err(|e| e.0)?;\n",
                    s(*dst)
                ));
            }
            Op::Replicate { dst, src, times } => {
                self.out.push_str(&format!(
                    "    {} = vl_ops::apply_replicate(&{}, {times}).map_err(|e| e.0)?;\n",
                    s(*dst), v(*src)
                ));
            }
            Op::LoadVar { dst, var } => {
                self.out.push_str(&format!("    {} = vars[{}].clone();\n", s(*dst), var));
            }
            Op::LoadPart { dst, var, hi, lo } => {
                self.out.push_str(&format!(
                    "    {} = Bits::part(&vars[{var}], {hi}, {lo}).map_err(|e| e.0)?;\n",
                    s(*dst)
                ));
            }
            Op::AssignBlk { lv, src } => match lv {
                Lval::Var { var } => {
                    // Truncate to the DECLARED width (kernel commit parity;
                    // measured: a 64-bit const put onto a 1-bit reg made
                    // %b print the raw width).
                    self.out.push_str(&format!(
                        "    rt.store(vars, {var}, {}, {});\n",
                        v(*src),
                        d.vars[*var as usize].width
                    ));
                }
                _ => unreachable!("filtered in gen()"),
            },
            Op::AssignNba { lv, src } => match lv {
                Lval::Var { var } => {
                    self.out.push_str(&format!(
                        "    rt.nba({var}, {}, {});\n",
                        v(*src),
                        d.vars[*var as usize].width
                    ));
                }
                _ => unreachable!("filtered in gen()"),
            },
            Op::AssignNbaDelay { lv, src, amount } => match lv {
                Lval::Var { var } => {
                    self.out.push_str(&format!(
                        "    rt.nba_at({var}, {}, {}, slots[{amount}].to_u128_lossy() as u64);\n",
                        v(*src),
                        d.vars[*var as usize].width
                    ));
                }
                _ => unreachable!("filtered in gen()"),
            },
            Op::Delay { amount } => {
                // The segment scheduler's only suspension: the trailing
                // Delay turns into `d = ticks` + a state return.
                self.out
                    .push_str(&format!("    let d = slots[{amount}].to_u128_lossy() as u64;\n"));
            }
            Op::EndThread => {}
            Op::SysCall { id, fmt, args, .. } => match id {
                SysId::Display | SysId::Write => {
                    let fi = fmt.ok_or_else(|| err("$display with no format"))?;
                    let pieces = d
                        .strs
                        .get(fi as usize)
                        .ok_or_else(|| err("format index out of range"))?;
                    let parts = args
                        .iter()
                        .map(|a| format!("({}.clone(), {}, {})", v(a.slot), a.signed, a.is_time))
                        .collect::<Vec<_>>()
                        .join(", ");
                    self.out
                        .push_str(&format!("    rt.display(&{}, &[{parts}]);\n", pieces_lit(pieces)));
                    if *id == SysId::Display {
                        self.out.push_str("    rt.newline();\n");
                    }
                }
                SysId::Finish => {
                    self.out.push_str("    rt.finish_now();\n    return Ok(Susp::Done);\n");
                }
                other => return Err(err(&format!("syscall {other:?}"))),
            },
            other => return Err(err(&format!("op {other:?}"))),
        }
        Ok(())
    }
}

/// Emit a pieces literal: `&[FmtPiece::...]` (a fresh Vec per display —
/// the formatting contract lives in riv_kernel, not in this data).
fn pieces_lit(pieces: &[FmtPiece]) -> String {
    let items = pieces
        .iter()
        .map(|p| match p {
            FmtPiece::Text(t) => format!("riv_ir::FmtPiece::Text({t:?}.to_string())"),
            FmtPiece::Spec { ch, width, zero_pad, arg } => format!(
                "riv_ir::FmtPiece::Spec {{ ch: '{ch}', width: {width}, zero_pad: {zero_pad}, arg: {arg} }}"
            ),
        })
        .collect::<Vec<_>>()
        .join(", ");
    format!("[{items}]")
}

/// The embedded runtime: the ADR-0001 scheduler in miniature — active
/// FIFO (declaration order) → inactive region (#0) → NBA batch → wheel
/// advance (delayed NBAs due at the new time commit before the woken
/// threads run; kernel run-loop order). Single-threaded host, no true
/// concurrency (PLAN §3).
const RUNTIME: &str = r##"type ThreadFn = fn(&mut Rt, &mut Vec<Bits>, &mut Vec<Bits>, &mut u32) -> Result<Susp, Box<dyn std::error::Error>>;

enum Susp {
    /// Suspend onto the wheel at now + ticks (0 routes to the inactive
    /// region — the scheduler does the routing, mirroring Resume).
    Delay(u64),
    /// #0 yield: re-queued through the inactive region in the same slot.
    Inactive,
    Done,
}

struct Rt {
    timescale: String,
    now: u64,
    nba: Vec<(usize, u32, Bits)>,
    nba_due: std::collections::BTreeMap<u64, Vec<(usize, u32, Bits)>>,
    out: String,
    finished: bool,
}

impl Rt {
    fn new(timescale: &str) -> Rt {
        Rt {
            timescale: timescale.to_string(),
            now: 0,
            nba: Vec::new(),
            nba_due: std::collections::BTreeMap::new(),
            out: String::new(),
            finished: false,
        }
    }
    /// Blocking write: truncate to the declared width, then project
    /// 2-state (the storage boundary contract).
    fn store(&self, vars: &mut Vec<Bits>, id: usize, v: Bits, width: u32) {
        vars[id] = vl_values::Limbs::padded(&v, width)
            .pack(width)
            .map_err(|e| e.0)
            .unwrap_or_else(|_| vars[id].clone())
            .to_2state()
            .map_err(|e| e.0)
            .unwrap_or_else(|_| vars[id].clone());
    }
    fn nba(&mut self, id: usize, v: Bits, width: u32) {
        self.nba.push((id, width, v));
    }
    /// Intra-assignment delay NBA: sampled now, committed in the NBA
    /// region of the slot now+amount (the process does not suspend).
    fn nba_at(&mut self, id: usize, v: Bits, width: u32, amount: u64) {
        if amount == 0 {
            self.nba.push((id, width, v));
        } else {
            self.nba_due.entry(self.now + amount).or_default().push((id, width, v));
        }
    }
    fn apply_nba(&mut self, vars: &mut Vec<Bits>) {
        for (id, width, v) in std::mem::take(&mut self.nba) {
            self.store(vars, id, v, width);
        }
    }
    fn display(&mut self, pieces: &[riv_ir::FmtPiece], args: &[(Bits, bool, bool)]) {
        let scale = riv_kernel::unit_ratio_pub(&self.timescale).unwrap_or(1) as u64;
        self.out.push_str(&riv_kernel::render_pieces(pieces, args, scale));
    }
    fn newline(&mut self) {
        self.out.push('\n');
    }
    fn finish_now(&mut self) {
        self.finished = true;
    }
    fn flush(self, _vars: &mut Vec<Bits>) {
        print!("{}", self.out);
    }

    fn run_all(&mut self, vars: &mut Vec<Bits>, slot_frames: &mut Vec<Vec<Bits>>, threads: &[ThreadFn]) {
        let n = threads.len();
        let mut states = vec![0u32; n];
        let mut active: std::collections::VecDeque<usize> = (0..n).collect();
        let mut inactive: std::collections::VecDeque<usize> = std::collections::VecDeque::new();
        let mut wheel: std::collections::BTreeMap<u64, Vec<usize>> = std::collections::BTreeMap::new();
        loop {
            // 1. Active region: FIFO drain in declaration order.
            while let Some(ti) = active.pop_front() {
                let susp = (threads[ti])(self, vars, &mut slot_frames[ti], &mut states[ti])
                    .unwrap_or_else(|e| {
                        eprintln!("runtime error: {e}");
                        std::process::exit(1);
                    });
                match susp {
                    Susp::Delay(t) if t == 0 => inactive.push_back(ti),
                    Susp::Delay(t) => wheel.entry(self.now + t).or_default().push(ti),
                    Susp::Inactive => inactive.push_back(ti),
                    Susp::Done => {}
                }
                if self.finished {
                    return;
                }
            }
            // 2. Inactive region (#0 resumes), drained to stability.
            while let Some(ti) = inactive.pop_front() {
                let susp = (threads[ti])(self, vars, &mut slot_frames[ti], &mut states[ti])
                    .unwrap_or_else(|e| {
                        eprintln!("runtime error: {e}");
                        std::process::exit(1);
                    });
                match susp {
                    Susp::Delay(t) if t == 0 => inactive.push_back(ti),
                    Susp::Delay(t) => wheel.entry(self.now + t).or_default().push(ti),
                    Susp::Inactive => inactive.push_back(ti),
                    Susp::Done => {}
                }
                if self.finished {
                    return;
                }
            }
            // 3. NBA batch commit (issue order, same slot).
            self.apply_nba(vars);
            // 4. Wheel advance: delayed NBAs due at the new time commit
            // first, then the woken threads re-enter the active region.
            let Some((&at, _)) = wheel.iter().next() else {
                break;
            };
            self.now = at;
            if let Some(updates) = self.nba_due.remove(&at) {
                self.nba.extend(updates);
            }
            self.apply_nba(vars);
            if let Some(woken) = wheel.remove(&at) {
                for ti in woken {
                    active.push_back(ti);
                }
            }
        }
    }
}
"##;
